			separator := 0
			if dataSeen {
				separator = 1
			}
			if len(data)+separator+len(value) > maxSSEFrameBytes {
				return "", nil, platform.NewError(platform.CodeBudgetExceeded, false, "事件帧超过载荷上限")
			}
